const roles={manager:'Quản lý',pharmacist:'Dược sĩ',cashier:'Thu ngân'};

function renderInlineMarkdown(text){
  const value=String(text??'');
  const cleanPlain=value=>String(value??'').replace(/\*/g,'');
  const parts=[];
  const re=/(\*\*[^*\n]+\*\*|\*[^*\n]+\*|`[^`\n]+`)/g;
  let last=0,match,index=0;
  while((match=re.exec(value))!==null){
    if(match.index>last)parts.push(cleanPlain(value.slice(last,match.index)));
    const token=match[0];
    if(token.startsWith('**'))parts.push(<strong key={'b'+index}>{token.slice(2,-2)}</strong>);
    else if(token.startsWith('*'))parts.push(<em key={'i'+index}>{token.slice(1,-1)}</em>);
    else parts.push(<code key={'c'+index}>{token.slice(1,-1)}</code>);
    last=match.index+token.length;
    index+=1;
  }
  if(last<value.length)parts.push(cleanPlain(value.slice(last)));
  return parts;
}

function MarkdownMessage({text}){
  const lines=String(text??'').split(/\r?\n/);
  const blocks=[];
  let listItems=[];
  let listType=null;
  let key=0;
  const flushList=()=>{
    if(!listItems.length)return;
    const Tag=listType==='ol'?'ol':'ul';
    blocks.push(<Tag key={'list'+key++}>{listItems.map((item,i)=><li key={i}>{renderInlineMarkdown(item)}</li>)}</Tag>);
    listItems=[];
    listType=null;
  };
  for(let lineIndex=0;lineIndex<lines.length;lineIndex++){
    const rawLine=lines[lineIndex];
    const cells=line=>line.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(x=>x.trim());
    if(rawLine.includes('|') && lineIndex+1<lines.length && cells(lines[lineIndex+1]).every(c=>/^:?-{3,}:?$/.test(c))){
      flushList();const header=cells(rawLine);const rows=[];lineIndex+=2;
      while(lineIndex<lines.length&&lines[lineIndex].includes('|')){rows.push(cells(lines[lineIndex]));lineIndex++}lineIndex--;
      blocks.push(<div className="md-table-scroll" key={'table'+key++}><table><thead><tr>{header.map((c,i)=><th key={i}>{renderInlineMarkdown(c)}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{header.map((_,j)=><td key={j}>{renderInlineMarkdown(r[j]||'')}</td>)}</tr>)}</tbody></table></div>);continue;
    }
    if(rawLine.trim().startsWith('>')){flushList();blocks.push(<blockquote key={'quote'+key++}>{renderInlineMarkdown(rawLine.trim().slice(1).trim())}</blockquote>);continue;}
    if(rawLine.trim()==='---'){flushList();blocks.push(<hr key={'hr'+key++}/>);continue;}

    const line=rawLine.trimEnd();
    const ordered=line.match(/^\s*\d+[.)]\s+(.+)$/);
    const bullet=line.match(/^\s*[-•*]\s+(.+)$/);
    if(ordered){
      if(listType&&listType!=='ol')flushList();
      listType='ol';
      listItems.push(ordered[1]);
      continue;
    }
    if(bullet){
      if(listType&&listType!=='ul')flushList();
      listType='ul';
      listItems.push(bullet[1]);
      continue;
    }
    flushList();
    if(!line.trim()){
      blocks.push(<div key={'gap'+key++} className="md-gap"/>);
      continue;
    }
    const heading=line.match(/^\s*#{1,3}\s+(.+)$/);
    if(heading){
      blocks.push(<div key={'h'+key++} className="md-heading">{renderInlineMarkdown(heading[1])}</div>);
      continue;
    }
    blocks.push(<p key={'p'+key++}>{renderInlineMarkdown(line)}</p>);
  }
  flushList();
  return <>{blocks}</>;
}
const navigation=[['dashboard','Tổng quan',LayoutDashboard],['pos','Bán hàng',ShoppingBag],['medicines','Thuốc',Pill],['batches','Lô & tồn kho',Package],['invoices','Hóa đơn',BookOpen],['alerts','Cảnh báo',TriangleAlert],['suppliers','Nhà cung cấp',Truck],['reports','Báo cáo',ChartNoAxesCombined],['users','Phân quyền',Users],['settings','Thiết lập',Settings]];
const rolePages={manager:['dashboard','pos','medicines','batches','invoices','alerts','suppliers','reports','users','settings'],pharmacist:['dashboard','pos','medicines','batches','invoices','alerts','settings'],cashier:['dashboard','pos','medicines','invoices','settings']};
function ErrorBox({error}){return error ? <div className="error" role="alert">{error}</div>:null}
function Empty({text='Chưa có dữ liệu. Hãy thêm bản ghi đầu tiên.'}){return <div className="empty"><Package size={32}/><b>Không có dữ liệu</b><span>{text}</span></div>}
function Badge({children,tone='green'}){return <span className={'badge '+tone}>{children}</span>}
function Button({children,secondary=false,...props}){return <button className={secondary?'button secondary':'button'} {...props}>{children}</button>}
function ActionPill({children,tone='primary',icon:Icon,...props}){return <button className={`action-pill ${tone}`} {...props}>{Icon&&<Icon size={14}/>}<span>{children}</span></button>}
function Pagination({page,pages,total,start,end,onChange,label='bản ghi'}){
  if(total<=0||pages<=1)return null;
  const first=Math.max(1,Math.min(page-2,pages-4));
  const numbers=Array.from({length:Math.min(5,pages)},(_,i)=>first+i);
  return <nav className="data-pagination" aria-label={`Phân trang ${label}`}>
    <span className="pagination-count">Hiển thị {start}–{end} / {total} {label}</span>
    <div className="pagination-controls">
      <button type="button" disabled={page===1} onClick={()=>onChange(page-1)} aria-label="Trang trước">‹</button>
      {numbers.map(n=><button key={n} type="button" className={page===n?'is-current':''} aria-label={`Trang ${n}`} aria-current={page===n?'page':undefined} onClick={()=>onChange(n)}>{n}</button>)}
      <button type="button" disabled={page===pages} onClick={()=>onChange(page+1)} aria-label="Trang sau">›</button>
    </div>
  </nav>;
}
const tableWeight={code:1.05,id:.85,name:2.7,medicine:2.5,medicine_name:2.5,supplier_name:2.15,category_id:1.5,unit_id:.85,min_stock:1.1,phone:1.25,address:2,active:1.1,quantity:1.05,expiry_date:1.45,created_at:1.35,customer:1.9,total:1.25,status:1.25,role:1.3,username:1.5,actions:1.2,reason:1.8};
function Table({columns,rows,empty,pageSize=10,minWidth=0}){
  const [requestedPage,setRequestedPage]=useState(1);
  const pages=Math.max(1,Math.ceil(rows.length/pageSize));
  const page=Math.min(requestedPage,pages);
  const start=(page-1)*pageSize;
  const shown=rows.slice(start,start+pageSize);
  const weights=columns.map(c=>c.width??tableWeight[c.key]??1.25);
  const weightSum=weights.reduce((a,b)=>a+b,0);
  if(!rows.length)return <Empty text={empty}/>;
  return <><div className="table-scroll"><table className="aligned-data-table" style={{minWidth:`${Math.max(minWidth,520,columns.length*155)}px`}}>
    <colgroup>{columns.map((c,i)=><col key={c.key} style={{width:`${(weights[i]/weightSum*100).toFixed(3)}%`}}/>)}</colgroup>
    <thead><tr>{columns.map(c=><th scope="col" key={c.key} className={'data-column-'+c.key}>{c.label}</th>)}</tr></thead>
    <tbody>{shown.map((r,i)=><tr key={r.id??start+i}>{columns.map(c=><td key={c.key} className={'data-column-'+c.key}>{c.render?c.render(r):String(r[c.key]??'—')}</td>)}</tr>)}</tbody>
  </table></div><Pagination page={page} pages={pages} total={rows.length} start={start+1} end={Math.min(start+pageSize,rows.length)} onChange={setRequestedPage} label="dòng"/></>;
}
function Modal({title,children,onClose,wide=false}){useEffect(()=>{const h=e=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',h);return()=>document.removeEventListener('keydown',h)},[onClose]);return <div className="overlay" onClick={onClose}><section role="dialog" aria-modal="true" aria-label={title} className={'modal '+(wide?'wide':'')} onClick={e=>e.stopPropagation()}><div className="modal-header"><h2>{title}</h2><button className="icon-button" aria-label="Đóng" onClick={onClose}><X/></button></div>{children}</section></div>}
function PageTitle({eyebrow,title,description,action}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow || 'NHÀ THUỐC AN TÂM'}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function useData(path){const[data,setData]=useState(null),[error,setError]=useState(''),[loading,setLoading]=useState(true);async function reload(){setError('');setLoading(true);try{setData(await api(path))}catch(e){setError(e.message)}finally{setLoading(false)}}useEffect(()=>{reload()},[path]);return{data,error,loading,reload}}
function Load({state,children}){return <><ErrorBox error={state.error}/>{state.loading?<div className="loading">Đang tải dữ liệu…</div>:state.error?<Button secondary onClick={state.reload}><RefreshCw size={16}/> Thử lại</Button>:children}</>}
class Boundary extends Component{state={error:false};static getDerivedStateFromError(){return{error:true}}render(){return this.state.error?<div className="panel"><h2>Không thể hiển thị màn hình</h2><p>Vui lòng tải lại trang. Nếu vẫn lỗi, gửi ảnh cửa sổ backend để kiểm tra.</p><Button onClick={()=>location.reload()}>Tải lại</Button></div>:this.props.children}}

function PasswordInput(props){
  const[visible,setVisible]=useState(false);
  useEffect(()=>{if(!props.value)setVisible(false)},[props.value]);
  const label=props['aria-label']||'Mật khẩu';
  return <span className="password-control"><input {...props} type={visible?'text':'password'}/><button type="button" className="password-eye" aria-label={(visible?'Ẩn ':'Hiện ')+label.toLowerCase()} aria-pressed={visible} title={visible?'Ẩn mật khẩu':'Hiện mật khẩu'} onClick={()=>setVisible(v=>!v)}>{visible?<EyeOff size={19}/>:<Eye size={19}/>}</button></span>
}
function Login({onLogin}){const[username,setUsername]=useState('admin'),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e){e.preventDefault();setBusy(true);setError('');try{onLogin(await send('/auth/login','POST',{username,password}))}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="login"><div className="login-story"><div className="brand"><span className="brand-icon"><img src="/an-tam-mark.png" alt=""/></span><span>An Tâm</span></div><div className="login-story-message"><span className="story-label">HỆ THỐNG QUẢN LÝ NHÀ THUỐC</span><h1>Vận hành gọn gàng.<br/>An tâm mỗi ngày.</h1><p>Quản lý thuốc, theo dõi lô và phục vụ khách hàng trong một không gian làm việc.</p></div></div><div className="login-form"><form onSubmit={submit}><div className="eyebrow">CHÀO MỪNG TRỞ LẠI</div><h2>Đăng nhập</h2><p>Sẵn sàng cho một ngày làm việc hiệu quả.</p><ErrorBox error={error}/><label>Tên đăng nhập<input autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} required/></label><label>Mật khẩu<PasswordInput aria-label="Mật khẩu" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><Button disabled={busy}>{busy?'Đang đăng nhập…':'Đăng nhập'}<ArrowRight size={18}/></Button><p className="login-help"><LockKeyhole size={16}/> Dùng tài khoản do quản lý nhà thuốc cấp.</p></form></div></div>}

function App(){const[user,setUser]=useState(null),[checking,setChecking]=useState(true),[page,setPage]=useState('dashboard'),[mobile,setMobile]=useState(false),[error,setError]=useState('');useEffect(()=>{api('/auth/me').then(setUser).catch(()=>{}).finally(()=>setChecking(false));const clear=()=>setUser(null);window.addEventListener('session-expired',clear);return()=>window.removeEventListener('session-expired',clear)},[]);if(checking)return <div className="loading full-loading"><img className="brand-loading pulse" src="/an-tam-mark.png" alt=""/> Đang mở An Tâm…</div>;if(!user)return <Login onLogin={u=>{setUser(u);setPage(u.role==='cashier'?'pos':'dashboard')}}/>;const allowed=n=>rolePages[user.role].includes(n[0]);async function logout(){try{await send('/auth/logout','POST',{});setUser(null)}catch(e){setError(e.message)}}const current=navigation.find(n=>n[0]===page);return <div className="app"><aside className={mobile?'sidebar open':'sidebar'}><div className="brand"><span className="brand-icon"><img src="/an-tam-mark.png" alt=""/></span><span>An Tâm</span></div><div className="nav-caption">KHÔNG GIAN {roles[user.role].toUpperCase()}</div><nav>{navigation.filter(allowed).map(([id,label,Icon])=><button key={id} className={page===id?'nav-item active':'nav-item'} onClick={()=>{setPage(id);setMobile(false);setError('')}}><Icon size={19}/><span>{label}</span>{page===id&&<ChevronRight size={15}/>}</button>)}</nav><div className="sidebar-bottom"><div className="avatar">{user.name.slice(0,1)}</div><div><b>{user.name}</b><small>{roles[user.role]}</small></div><button className="icon-button" title="Đăng xuất" onClick={logout}><LogOut size={17}/></button></div></aside><div className="main-shell"><header className="topbar"><button className="icon-button mobile-toggle" onClick={()=>setMobile(!mobile)} aria-label="Mở menu"><Menu/></button><div className="breadcrumb">An Tâm <ChevronRight size={14}/><b>{current?.[1]}</b></div><div className="topbar-right"><Badge tone="gray">{roles[user.role]}</Badge><span className="top-date">{new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span></div></header><main><ErrorBox error={error}/><Boundary key={page}>{page==='dashboard'?<Dashboard user={user} go={setPage}/>:page==='pos'?<POS user={user}/>:page==='batches'?<Batches user={user}/>:page==='invoices'?<Invoices user={user}/>:page==='alerts'?<Alerts/>:page==='reports'?<Reports/>:page==='users'?<Staff user={user}/>:page==='settings'?<SettingsPage user={user}/>:<Catalog key={page} type={page} user={user}/>}</Boundary></main></div><AIChat user={user} MarkdownMessage={MarkdownMessage} page={page} onNavigate={setPage}/></div>}

function Dashboard({go,user}){const state=useData('/dashboard'),d=state.data;const title=user.role==='manager'?'Trung tâm điều hành':user.role==='pharmacist'?'Bàn làm việc Dược sĩ':'Ca bán hàng hôm nay';const desc=user.role==='manager'?'Theo dõi bán hàng, tồn kho và hoạt động nhà thuốc.':user.role==='pharmacist'?'Tập trung vào thuốc, lô, hạn dùng và kiểm kê.':'Bán hàng nhanh, tra cứu tồn và theo dõi hóa đơn trong ca.';return <><PageTitle eyebrow={`${roles[user.role].toUpperCase()} · HÔM NAY`} title={title} description={desc} action={<Button onClick={()=>go('pos')}><Plus size={18}/> Tạo đơn bán</Button>}/><Load state={state}>{d&&<><div className={'welcome role-'+user.role}><div><span className="eyebrow">XIN CHÀO, {user.name.toUpperCase()}</span><h2>{user.role==='manager'?'Mọi chỉ số quan trọng trong một màn hình.':user.role==='pharmacist'?'Ưu tiên an toàn thuốc và độ chính xác tồn kho.':'Sẵn sàng phục vụ khách hàng.'}</h2><p>{user.role==='manager'?'Kiểm tra tồn kho và cảnh báo hạn dùng trước khi bắt đầu.':user.role==='pharmacist'?'Theo dõi lô, nhập thuốc và kiểm tra hạn dùng của từng lô.':'Trợ lý AI có thể giúp tra tồn, giá bán và quy trình bằng câu hỏi tự nhiên.'}</p></div><div className="welcome-art"><div className="medical-cross">✚</div><Pill size={48}/></div></div>{user.role==='manager'?<div className="stats"><Stat label="Doanh thu tháng" value={money(d.revenue)} icon={WalletCards} sub={`${d.invoice_count} hóa đơn đã thanh toán`}/><Stat label="Nhân viên hoạt động" value={d.staff_count} icon={Users} sub="Tài khoản đang được phép truy cập"/><Stat label="Danh mục thuốc" value={d.medicine_count} icon={Pill} sub="Thuốc đang kinh doanh"/><Stat label="Lô cần chú ý" value={d.alerts.expiry.length} icon={TriangleAlert} sub="Hết hạn hoặc trong 90 ngày" tone="orange"/></div>:user.role==='pharmacist'?<div className="stats"><Stat label="Tồn có thể bán" value={d.available_units} icon={Boxes} sub={`${d.available_batches} lô còn hạn`}/><Stat label="Sắp hết hạn" value={d.expiring_batches} icon={Clock3} sub="Trong 90 ngày tới" tone="orange"/><Stat label="Tồn dưới ngưỡng" value={d.alerts.low_stock.length} icon={TriangleAlert} sub="Cần kiểm tra kế hoạch bổ sung" tone="orange"/><Stat label="Lô đã hết hạn" value={d.expired_batches} icon={Package} sub="Cần xử lý, không được bán" tone="orange"/></div>:<div className="stats"><Stat label="Doanh số ca hôm nay" value={money(d.today_sales)} icon={WalletCards} sub="Chỉ hóa đơn do bạn tạo"/><Stat label="Hóa đơn hôm nay" value={d.today_invoice_count} icon={BookOpen} sub="Đã thanh toán"/><Stat label="Lô đang bán" value={d.available_batches} icon={Package} sub="Còn hạn và còn tồn"/><Stat label="Thuốc tồn thấp" value={d.low_stock_count} icon={TriangleAlert} sub="Để chủ động khi bán" tone="orange"/></div>}<div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><h2>Việc cần chú ý</h2><p>{user.role==='cashier'?'Một số lô gần hạn để tránh chọn nhầm khi bán.':'Các lô cần được kiểm tra theo hạn dùng.'}</p></div>{user.role!=='cashier'&&<button className="text-button" onClick={()=>go('alerts')}>Xem tất cả <ArrowRight size={15}/></button>}</div><ExpiryTable rows={(d.alerts?.expiry||[]).slice(0,5)}/></section><section className="panel quick"><span className="eyebrow">THAO TÁC THEO VAI TRÒ</span><h2>Bắt đầu công việc</h2>{(user.role==='manager'?[['reports','Xem báo cáo','Doanh thu và giá trị tồn kho',ChartNoAxesCombined],['users','Phân quyền','Quản lý tài khoản và vai trò',Users],['alerts','Cảnh báo thuốc','Kiểm tra tồn kho và hạn dùng',TriangleAlert]]:user.role==='pharmacist'?[['batches','Kiểm tra lô & tồn','Hạn dùng, nhập lô và theo dõi kho',Package],['alerts','Xử lý cảnh báo','Theo dõi lô gần hạn và tồn thấp',TriangleAlert],['medicines','Danh mục thuốc','Tra cứu và cập nhật thông tin thuốc',Pill]]:[['pos','Bán hàng tại quầy','Tìm thuốc và thanh toán',ShoppingBag],['invoices','Tra cứu hóa đơn','Xem và in hóa đơn',BookOpen],['medicines','Tra cứu thuốc','Xem thông tin thuốc và giá bán',Pill]]).map(([id,t,sub,Icon])=><button key={id} onClick={()=>go(id)}><span className="quick-icon"><Icon size={21}/></span><span><b>{t}</b><small>{sub}</small></span><ChevronRight size={17}/></button>)}<div className="note"><ShieldCheck size={21}/><span>AI hỗ trợ tra cứu dữ liệu nhà thuốc. Các thao tác cập nhật được phân quyền theo vai trò.</span></div></section></div></>}</Load></>}

function Stat({label,value,sub,icon:Icon,tone=''}){return <div className={'stat '+tone}><div><span>{label}</span><Icon size={20}/></div><strong>{value}</strong><small>{sub}</small></div>}
function ExpiryTable({rows}){return <Table rows={rows} empty="Chưa có lô nào cần cảnh báo trong khoảng đã chọn." columns={[{key:'medicine_name',label:'THUỐC / LÔ',render:r=><><b>{r.medicine_name}</b><small>{r.code}</small></>},{key:'quantity',label:'TỒN',render:r=>`${r.quantity} ${r.unit}`},{key:'expiry_date',label:'HẠN DÙNG',render:r=>date(r.expiry_date)},{key:'days_left',label:'TRẠNG THÁI',render:r=><Badge tone={r.days_left<=0?'red':'orange'}>{r.days_left<=0?'Hết hạn':`Còn ${r.days_left} ngày`}</Badge>}]}/>}

